toolUseResult.stdout:
    }
    if (pick == FM_VOICES)
        for (n = 0; n < FM_VOICES; n++) {
            if (voice[n].fade || (!two_cores && (n & 1)))
                continue;
            if (pick == FM_VOICES || ctl[n].age < ctl[pick].age)
