#include <stdio.h>
static long n;
static void gfx_pixel(unsigned x, unsigned y, unsigned c){(void)x;(void)y;(void)c;n++;}
void gfx_line(int x0, int y0, int x1, int y1, unsigned colour)
{
    int dx = x1 > x0 ? x1 - x0 : x0 - x1, sx = x1 > x0 ? 1 : -1;
