        return -quarter[k - 128];
    return quarter[256 - k];
}

/* The engine's side: one block's output (stereo, 24-bit), while the
 * patch view shows; or, at rest, the ring cleared once. */
void spectrum_feed(const s32 *out, u32 frames)
{
    u32 n, p = spec_pos;

    if (!out) {
        if (!ring_clear) {
            for (n = 0; n < SPEC_N; n++)
                spec_ring[n] = 0;
            ring_clear = 1;
        }
        return;
    }
    for (n = 0; n < frames; n++)
        spec_ring[(p + n) & (SPEC_N - 1u)] = (s16)(out[2 * n] >> 8);
    spec_pos = p + frames;
    ring_clear = 0;
}

static s32 re[SPEC_N], im[SPEC_N];
static u32 power[SPEC_N / 2];

/* The FFT of the ring now into the bars' heights (0 to height); returns 0,
 * leaving bars as they are, if the ring holds only silence. */
u32 spectrum_compute(u8 *bars, u32 height)
{
    u32 i, j, start = spec_pos, any = 0, size;

    for (i = 0; i < SPEC_N; i++) {
        s32 x = spec_ring[(start + i) & (SPEC_N - 1u)];
        any |= (u32)x;
        /* Hann: (1 - cos) / 2, Q15. */
        re[i] = (x * ((32768 - cos256(i)) >> 1)) >> 15;
        im[i] = 0;
    }
    if (!any)
        return 0;
    /* Bit-reversed order, then radix-2 butterflies, halving each stage. */
    for (i = 1, j = 0; i < SPEC_N; i++) {
        u32 bit = SPEC_N >> 1;
        while (j & bit) {
            j ^= bit;
            bit >>= 1;
        }
        j |= bit;
        if (i < j) {
            s32 t = re[i];
            re[i] = re[j];
            re[j] = t;
        }
    }
    for (size = 2; size <= SPEC_N; size <<= 1) {
        u32 half = size >> 1, step = SPEC_N / size, k;
        for (k = 0; k < half; k++) {
            s32 wr = cos256(k * step), wi = -cos256(k * step + 192u);   /* e^(-i 2 pi k / size) */
            for (i = k; i < SPEC_N; i += size) {
                u32 b = i + half;
                s32 tr = (re[b] * wr - im[b] * wi) >> 15, ti = (re[b] * wi + im[b] * wr) >> 15;
                re[b] = (re[i] - tr) >> 1;
                im[b] = (im[i] - ti) >> 1;
                re[i] = (re[i] + tr) >> 1;
                im[i] = (im[i] + ti) >> 1;
            }
        }
    }
    for (i = 1; i < SPEC_N / 2; i++)
        power[i] = (u32)(re[i] * re[i]) + (u32)(im[i] * im[i]);
    power[0] = 0;
    for (j = 0; j < SPEC_BARS; j++) {
        u32 lo = (edge[j] + 15u) >> 4, hi = edge[j + 1] >> 4, p = 0, lg, q;
        if (lo > hi) {
            u32 c = (edge[j] + edge[j + 1]) >> 1, k0 = c >> 4, f = c & 15u;
            p = (power[k0] >> 4) * (16u - f) + (k0 + 1 < SPEC_N / 2 ? (power[k0 + 1] >> 4) * f : 0);
        } else {
            for (i = lo; i <= hi && i < SPEC_N / 2; i++)
                if (power[i] > p)
                    p = power[i];
        }
        /* log2 of the power in sixteenths; a full-scale sine's peak bin
         * is about 2^26 here, 60 dB below it about 2^6. */
        if (!p) {
            bars[j] = 0;
            continue;
        }
        lg = 31u - (u32)__builtin_clz(p);
        q = lg * 16u + (lg >= 4 ? (p >> (lg - 4)) & 15u : 0);
        bars[j] = (u8)(q <= 6u * 16u ? 0 : q >= 26u * 16u ? height : (q - 6u * 16u) * height / (20u * 16u));
    }
    return 1;
}

