body=s[i:]
new='''/* The transform, in three steps so that each is a part of the screen's
 * drawing within its budget (views.c): spectrum_start takes the ring and
 * windows it (0 if it holds only silence), spectrum_stages runs stages
 * first to last - 1 of the eight, spectrum_bars makes the bars. */
u32 spectrum_start(void)
{
    u32 i, j, start = spec_pos, any = 0;

    for (i = 0; i < SPEC_N; i++)
        any |= (u32)spec_ring[i];
    if (!any)
        return 0;
    for (i = 0; i < SPEC_N; i++) {
        s32 x = spec_ring[(start + i) & (SPEC_N - 1u)];
        /* Hann: (1 - cos) / 2, Q15. */
        re[i] = (x * ((32768 - cos256(i)) >> 1)) >> 15;
        im[i] = 0;
    }
    /* Bit-reversed order for the butterflies. */
    for (i = 1, j = 0; i < SPEC_N; i++) {
        u32 bit = SPEC_N >> 1;
        while (j & bit) {
            j ^= bit;
            bit >>= 1;
        }
        j |= bit;
        if (i < j) {
            s32 t = re[i];
            re[i] = re[j];
            re[j] = t;
        }
    }
    return 1;
}

/* Radix-2 butterflies, each stage halving the values. */
void spectrum_stages(u32 first, u32 last)
{
    u32 stage, i;

    for (stage = first; stage < last; stage++) {
        u32 size = 2u << stage, half = size >> 1, step = SPEC_N / size, k;
        for (k = 0; k < half; k++) {
            s32 wr = cos256(k * step), wi = -cos256(k * step + 192u);   /* e^(-i 2 pi k / size) */
            for (i = k; i < SPEC_N; i += size) {
                u32 b = i + half;
                s32 tr = (re[b] * wr - im[b] * wi) >> 15, ti = (re[b] * wi + im[b] * wr) >> 15;
                re[b] = (re[i] - tr) >> 1;
                im[b] = (im[i] - ti) >> 1;
                re[i] = (re[i] + tr) >> 1;
                im[i] = (im[i] + ti) >> 1;
            }
        }
    }
}

/* The bars' heights (0 to height) from the transform. */
void spectrum_bars(u8 *bars, u32 height)
{
    u32 i, j;

    for (i = 1; i < SPEC_N / 2; i++)
        power[i] = (u32)(re[i] * re[i]) + (u32)(im[i] * im[i]);
    power[0] = 0;
    for (j = 0; j < SPEC_BARS; j++) {
        u32 lo = (edge[j] + 15u) >> 4, hi = edge[j + 1] >> 4, p = 0, lg, q;
        if (lo > hi) {
            u32 c = (edge[j] + edge[j + 1]) >> 1, k0 = c >> 4, f = c & 15u;
            p = (power[k0] >> 4) * (16u - f) + (k0 + 1 < SPEC_N / 2 ? (power[k0 + 1] >> 4) * f : 0);
        } else {
            for (i = lo; i <= hi && i < SPEC_N / 2; i++)
                if (power[i] > p)
                    p = power[i];
        }
        /* log2 of the power in sixteenths; a full-scale sine's peak bin
         * is about 2^26 here, 60 dB below it about 2^6. */
        if (!p) {
            bars[j] = 0;
            continue;
        }
        lg = 31u - (u32)__builtin_clz(p);
        q = lg * 16u + (lg >= 4 ? (p >> (lg - 4)) & 15u : 0);
        bars[j] = (u8)(q <= 6u * 16u ? 0 : q >= 26u * 16u ? height : (q - 6u * 16u) * height / (20u * 16u));
    }
}
